import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.44aEvdQQ.js";const y=JSON.parse('{"title":"The Talent Siphon","description":"","frontmatter":{"title":"The Talent Siphon","order":5},"headers":[],"relativePath":"about/chapters/05-the-talent-siphon.md","filePath":"about/chapters/05-the-talent-siphon.md"}'),r={name:"about/chapters/05-the-talent-siphon.md"};function l(s,e,i,h,d,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="_05-the-talent-siphon" tabindex="-1">05.<br>The Talent Siphon <a class="header-anchor" href="#_05-the-talent-siphon" aria-label="Permalink to &quot;05.&lt;br&gt;The Talent Siphon&quot;">​</a></h3><h4 id="levels-and-ladders" tabindex="-1">Levels and Ladders <a class="header-anchor" href="#levels-and-ladders" aria-label="Permalink to &quot;Levels and Ladders&quot;">​</a></h4><p>In reality, no-one works for a single employer forever anymore. Instead of hoping your best people stay (and do not ask for consistent raises), it&#39;s important to get ahead of the narrative and define what you offer your people when they arrive with hope and energy. Ironically, the more you embrace the reality that some day they will work elsewhere (but that you&#39;re going to give them the finest preparation for the world), the longer they will want to stay with you, to repay the effort you&#39;ve invested in their career (not just <em>this</em> job and what they&#39;re going to do for you).</p><blockquote><p>The more closely you define and help develop and individual&#39;s career, the more likely you are going to have a long-term employee.</p><p>— <em>Simple Numbers. Straight Talk, Big Profits!</em></p></blockquote><p>By investing in people at the level they&#39;re at, you develop a team with high standards. I call this the Talent Siphon. Using four levels to label each employees role and status:</p><ul><li>Designer, Level One (most junior)</li><li>Designer, Level Two</li><li>Designer, Level Three</li><li>Designer, Level Four (most senior)</li></ul><p>Most small firms do not need three Level Four designers, they need a range of skill levels that siphons, or pulls, each level into the next:</p><ul><li>Level Ones grow to become Level Twos</li><li>Level Twos grow to become Level Threes</li><li>Level Threes grow to become Level Fours</li></ul><p>By taking this approach you can set both the skills required for each level, and the accompanying salary range, based <em>on your needs!</em> Not the industry&#39;s needs, on yours.</p><h5 id="what-happens-when-level-fours-max-out-your-salary-range" tabindex="-1">What Happens When Level Fours Max Out Your Salary Range? <a class="header-anchor" href="#what-happens-when-level-fours-max-out-your-salary-range" aria-label="Permalink to &quot;What Happens When Level Fours Max Out Your Salary Range?&quot;">​</a></h5><p>You have an adult conversation and remind them of what you can afford, and the numerous non-monetary advantages of working for a small firm like yours. People are going to find more money elsewhere, both because bigger businesses with equally big ambitions need Staff Designers, but because your competitors will over-pay (based on market standards) your people, risking financial peril, all because they cannot find and teach Level One prospects. They cannot develop talent, which is why it becomes your winning advantage.</p>',11)])])}const m=a(r,[["render",l]]);export{y as __pageData,m as default};
